def paint(n: int, ops: list[list[int]]) -> list[list[int]]:
    from bisect import bisect_left

    boundaries = {1, n + 1}
    for op in ops:
        boundaries.add(op[1])
        boundaries.add(op[2] + 1)
    coords = sorted(boundaries)
    del boundaries

    segment_count = len(coords) - 1
    size = 1 << (segment_count - 1).bit_length()

    # Range-maximum tags; a point's value is the maximum on its root path.
    tags = [0] * (2 * size)

    # Successor DSU skips segments already finalized by a later erase.
    parent = list(range(segment_count + 1))
    counts = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def finalize(left, right):
        i = find(left)
        while i < right:
            position = size + i
            colour = 0
            while position:
                if tags[position] > colour:
                    colour = tags[position]
                position >>= 1

            if colour:
                counts[colour] = (
                    counts.get(colour, 0) + coords[i + 1] - coords[i]
                )

            parent[i] = find(i + 1)
            i = parent[i]

    for op in reversed(ops):
        left = bisect_left(coords, op[1])
        right = bisect_left(coords, op[2] + 1)

        if op[0] == 0:
            finalize(left, right)
        else:
            colour = op[3]
            left += size
            right += size

            while left < right:
                if left & 1:
                    if colour > tags[left]:
                        tags[left] = colour
                    left += 1
                if right & 1:
                    right -= 1
                    if colour > tags[right]:
                        tags[right] = colour
                left >>= 1
                right >>= 1

    finalize(0, segment_count)
    return [[colour, counts[colour]] for colour in sorted(counts)]
